from fractions import Fraction

def bisect_sqrt(c, a, b, steps):
    """Bisect [a, b], with a*a < c < b*b, for the root of c.
    Return the final (left, right) as Fractions."""
    c, a, b = Fraction(c), Fraction(a), Fraction(b)
    for _ in range(steps):
        m = (a + b) / 2
        if m * m < c:
            a = m
        else:
            b = m
    return a, b
